H.background();
const v = H.plot2d({ xMin: -1, xMax: 9, yMin: -1, yMax: 7 });
v.grid(); v.axes();
const p = P.p, q = Math.abs(P.q) < 1e-6 ? 1 : P.q;
const m = p / q; // fractional/decimal coefficient
const b = P.b;
v.fn(x => m * x + b, { color: H.colors.accent, width: 3 });
// staircase: from x=0 step "q to the right, p up", repeated
const startX = 0, startY = b;
v.dot(startX, startY, { r: 6, fill: H.colors.good });
const steps = 3;
for (let s = 0; s < steps; s++) {
  const x0 = startX + s * q, y0 = startY + s * p;
  // run (horizontal) then rise (vertical)
  v.line(x0, y0, x0 + q, y0, { color: H.colors.good, width: 2, dash: [5, 4] });
  v.line(x0 + q, y0, x0 + q, y0 + p, { color: H.colors.violet, width: 2, dash: [5, 4] });
}
